from django.db import migrations, models

# Palettes fournies à l'époque (codes) ; « perso » : couleurs modifiées ; « p<numéro> » : palette enregistrée.
FOURNIES = {"ocean", "foret", "ardoise", "prune", "terracotta", "graphite", "indigo"}
NOM = "Palette d'origine"


def convertir_palette_retiree(apps, schema_editor):
    """Une installation dont la palette n'est plus fournie garde ses quatre couleurs, enregistrées comme palette propre à
    l'installation (la gamme se dérive de ces couleurs, comme pour les palettes fournies). Base neuve : rien."""
    Instance, Palette = apps.get_model("parametres", "Instance"), apps.get_model("parametres", "PaletteEnregistree")
    for i in Instance.objects.exclude(palette__in=FOURNIES | {"perso"}).exclude(palette__regex=r"^p[0-9]+$"):
        p = Palette.objects.create(nom=NOM, principale=i.couleur_principale, accent=i.couleur_accent,
                                   fond=i.couleur_fond, texte=i.couleur_texte, gamme={})
        i.palette = f"p{p.pk}"
        i.save(update_fields=["palette"])


def revenir(apps, schema_editor):
    """Retour arrière : la palette de l'installation redevient « couleurs modifiées » (mêmes quatre couleurs)."""
    Instance, Palette = apps.get_model("parametres", "Instance"), apps.get_model("parametres", "PaletteEnregistree")
    for p in Palette.objects.filter(nom=NOM):
        Instance.objects.filter(palette=f"p{p.pk}").update(palette="perso")


